async function renderChart() {
  try {
    // Fetch live_data.json generated by ingest_media.py
    const response = await fetch('live_data.json');
    const data = await response.json();

    const ctx = document.getElementById('votingChart').getContext('2d');

    // Extract political bloc labels and values
    const labels = Object.keys(data.voting_intentions || {});
    const values = Object.values(data.voting_intentions || {});

    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: 'Projected Vote Share (%)',
          data: values,
          backgroundColor: [
            '#3B82F6', // Center / Liberal (Blue)
            '#EF4444', // Left / Progressive (Red)
            '#10B981', // Greens (Green)
            '#1E40AF', // Conservative (Dark Blue)
            '#6B21A8'  // Far Right (Purple)
          ],
          borderRadius: 8
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          y: {
            beginAtZero: true,
            max: 50,
            grid: { color: '#334155' },
            ticks: { color: '#94A3B8' }
          },
          x: {
            grid: { display: false },
            ticks: { color: '#94A3B8' }
          }
        }
      }
    });
  } catch (error) {
    console.error('Error loading live_data.json:', error);
  }
}

renderChart();
